// @vitest-environment jsdom
/* global describe, it, expect -- vitest globals (globals: true); declared for `eslint .` */
/**
 * PublishModal characterization (see publishModalHarness.tsx).
 *
 * publishModal.golden.json was captured once from the unmodified PublishModal (before its JSX sections were
 * moved to components/publishModal/) and is never regenerated by this test. For five scenarios (WordPress
 * connected, disconnected, every API failing, approval workflow with a live deployment, no website id) it
 * holds action sequences that reach every tab, panel and control (every initial action, then the controls
 * each action reveals, three levels deep). Each sequence is replayed from a fresh mount and must produce the
 * same record: service calls with arguments in order, direct fetch requests, confirm / alert, downloads,
 * events and prop callbacks; the DOM after the action and after 5 more seconds of timers (exact HTML, by
 * SHA-256; the HTML itself is stored gzipped for diffs); the focused element; and the available controls.
 * Open / close / reopen is pinned as well.
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { gunzipSync } from "node:zlib";
import { fixturesFrom, openCloseRecord, replay, type RunRecord, type ScenarioName } from "./publishModalHarness";

const here = dirname(fileURLToPath(import.meta.url));
const fx = fixturesFrom(JSON.parse(readFileSync(join(here, "publishModal.shapes.json"), "utf8")));
const golden = JSON.parse(readFileSync(join(here, "publishModal.golden.json"), "utf8")) as {
  scenarios: Record<ScenarioName, RunRecord[]>;
  openClose: unknown;
  blobs: Record<string, string>;
};
const html = (h: string) => (golden.blobs[h] ? gunzipSync(Buffer.from(golden.blobs[h], "base64")).toString("utf8") : "");
const firstDiff = (a: string, b: string) => { let i = 0; while (i < a.length && a[i] === b[i]) i++; return `at ${i}: golden …${a.slice(Math.max(0, i - 80), i + 120)}… actual …${b.slice(Math.max(0, i - 80), i + 120)}…`; };

describe("PublishModal: recorded interaction sequences", () => {
  for (const [scenario, runs] of Object.entries(golden.scenarios) as Array<[ScenarioName, RunRecord[]]>) {
    describe(scenario, () => {
      it.each(runs.map((r, i) => [i, r.steps.map((s) => `${s.kind} ${s.desc}`).join(" > ") || "(initial)", r] as const))("#%i %s", async (_i, _label, expected) => {
        const { rec, html: actualHtml, later } = await replay(scenario, fx, expected.steps);
        if (rec.dom !== expected.dom) throw new Error(`DOM after the last action differs ${firstDiff(html(expected.dom), actualHtml)}`);
        if (rec.domLater !== expected.domLater) throw new Error(`DOM 5s later differs ${firstDiff(html(expected.domLater), later)}`);
        expect(rec).toEqual(expected);
      }, 60_000);
    });
  }
});

describe("PublishModal: open / close / reopen", () => {
  it("renders nothing while closed and keeps its state across reopen", async () => {
    expect(await openCloseRecord(fx)).toEqual(golden.openClose);
  });
});
